import hashlib
import hmac
import os
import sqlite3
from pathlib import Path

DOCUMENTS = "documents"
ALGORITHM = "pbkdf2_sha256"
ITERATIONS = 240_000
SALT_BYTES = 16


class DocumentVault:
    """Stores each owner's documents under their own folder of the vault root."""

    def __init__(self, root, db_path=":memory:"):
        self.root = Path(root)
        self.root.mkdir(parents=True, exist_ok=True)
        self.conn = sqlite3.connect(db_path)
        self.conn.row_factory = sqlite3.Row
        self.conn.execute(
            f"CREATE TABLE IF NOT EXISTS {DOCUMENTS} ("
            "owner TEXT NOT NULL, name TEXT NOT NULL, share_hash TEXT, "
            "bytes INTEGER NOT NULL, PRIMARY KEY (owner, name))"
        )
        self.conn.commit()

    def _locate(self, owner, name):
        base = (self.root / owner).resolve()
        path = (base / name).resolve()
        if path == base or not path.is_relative_to(base):
            raise ValueError(f"{name!r} is outside the owner's folder")
        return path

    def _hash_share_password(self, password, salt=None, iterations=ITERATIONS):
        if salt is None:
            salt = os.urandom(SALT_BYTES)
        digest = hashlib.pbkdf2_hmac("sha256", password.encode(), salt, iterations)
        return f"{ALGORITHM}${iterations}${salt.hex()}${digest.hex()}"

    def _share_matches(self, password, stored):
        parts = stored.split("$")
        if len(parts) != 4 or parts[0] != ALGORITHM:
            return False
        candidate = self._hash_share_password(
            password, bytes.fromhex(parts[2]), int(parts[1])
        )
        return hmac.compare_digest(candidate, stored)

    def store(self, owner, name, data, share_password=None):
        path = self._locate(owner, name)
        path.parent.mkdir(parents=True, exist_ok=True)
        if isinstance(data, str):
            data = data.encode()
        path.write_bytes(data)
        share_hash = (
            self._hash_share_password(share_password) if share_password else None
        )
        self.conn.execute(
            f"INSERT OR REPLACE INTO {DOCUMENTS} (owner, name, share_hash, bytes) "
            "VALUES (?, ?, ?, ?)",
            (owner, name, share_hash, len(data)),
        )
        self.conn.commit()
        return name

    def fetch(self, owner, name):
        return self._locate(owner, name).read_bytes()

    def unlock(self, owner, name, password):
        row = self.conn.execute(
            f"SELECT share_hash FROM {DOCUMENTS} WHERE owner = ? AND name = ?",
            (owner, name),
        ).fetchone()
        if row is None or row["share_hash"] is None:
            return False
        return self._share_matches(password, row["share_hash"])

    def documents_for(self, owner):
        rows = self.conn.execute(
            f"SELECT name, bytes FROM {DOCUMENTS} WHERE owner = ? ORDER BY name",
            (owner,),
        ).fetchall()
        return [dict(row) for row in rows]

    def total_bytes(self, owner):
        row = self.conn.execute(
            f"SELECT COALESCE(SUM(bytes), 0) FROM {DOCUMENTS} WHERE owner = ?",
            (owner,),
        ).fetchone()
        return row[0]

    def remove(self, owner, name):
        path = self._locate(owner, name)
        if not path.is_file():
            raise FileNotFoundError(name)
        path.unlink()
        self.conn.execute(
            f"DELETE FROM {DOCUMENTS} WHERE owner = ? AND name = ?", (owner, name)
        )
        self.conn.commit()

"""Issue and check signed session tokens."""

import base64
import hashlib
import hmac
import json
import os
import time

DEFAULT_TTL = 3600
SHARD_COUNT = 8
FIELD_SEP = "."


def _session_secret():
    return os.environ["SESSION_SECRET"].encode()


def _b64(raw):
    return base64.urlsafe_b64encode(raw).decode().rstrip("=")


def _unb64(text):
    return base64.urlsafe_b64decode(text + "=" * (-len(text) % 4))


def _sign(payload):
    return hmac.new(_session_secret(), payload, hashlib.sha256).hexdigest()


def issue(user_id, issued_at=None, ttl=DEFAULT_TTL):
    issued_at = int(issued_at if issued_at is not None else time.time())
    payload = json.dumps(
        {"user": user_id, "iat": issued_at, "exp": issued_at + ttl}, sort_keys=True
    ).encode()
    return _b64(payload) + FIELD_SEP + _sign(payload)


def _split(token):
    encoded, separator, signature = token.partition(FIELD_SEP)
    if not separator or not signature:
        raise ValueError("token is not well formed")
    return _unb64(encoded), signature


def verify(token, now=None):
    try:
        payload, signature = _split(token)
    except Exception:
        return None
    if not hmac.compare_digest(_sign(payload), signature):
        return None
    claims = json.loads(payload)
    moment = int(now if now is not None else time.time())
    if claims["exp"] <= moment:
        return None
    return claims


def seconds_remaining(token, now=None):
    claims = verify(token, now)
    if claims is None:
        return 0
    return claims["exp"] - int(now if now is not None else time.time())


def renew(token, now=None, ttl=DEFAULT_TTL):
    claims = verify(token, now)
    if claims is None:
        raise PermissionError("token is not valid")
    moment = int(now if now is not None else time.time())
    return issue(claims["user"], moment, ttl)


def shard_for(user_id):
    """Pick the session-store shard for a user; MD5 here is a bucketing choice."""
    digest = hashlib.md5(user_id.encode(), usedforsecurity=False).hexdigest()
    return int(digest[:8], 16) % SHARD_COUNT

"""Import CSV rows into one of the known report tables."""

import argparse
import csv
import sqlite3

TABLES = {
    "contacts": ("name", "email", "phone"),
    "orders": ("reference", "customer", "total_cents"),
}


def open_db(db_path=":memory:"):
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    for table, columns in TABLES.items():
        definition = ", ".join(f"{column} TEXT" for column in columns)
        conn.execute(f"CREATE TABLE IF NOT EXISTS {table} ({definition})")
    conn.commit()
    return conn


def _table(name):
    """Resolve a caller-supplied table name against the known tables."""
    if name not in TABLES:
        raise KeyError(name)
    return name


def import_rows(conn, table, rows):
    columns = TABLES[_table(table)]
    placeholders = ", ".join("?" for _ in columns)
    prepared = [tuple(str(value) for value in row) for row in rows]
    for row in prepared:
        if len(row) != len(columns):
            raise ValueError(f"expected {len(columns)} values, got {len(row)}")
    conn.executemany(
        f"INSERT INTO {table} ({', '.join(columns)}) VALUES ({placeholders})", prepared
    )
    conn.commit()
    return len(prepared)


def import_csv(conn, table, path):
    columns = TABLES[_table(table)]
    with open(path, newline="", encoding="utf-8") as handle:
        reader = csv.reader(handle)
        header = next(reader, None)
        if header != list(columns):
            raise ValueError(f"header must be {','.join(columns)}")
        return import_rows(conn, table, list(reader))


def row_count(conn, table):
    row = conn.execute(f"SELECT COUNT(*) FROM {_table(table)}").fetchone()
    return row[0]


def sample(conn, table, limit=3):
    columns = TABLES[_table(table)]
    rows = conn.execute(
        f"SELECT {', '.join(columns)} FROM {table} LIMIT ?", (limit,)
    ).fetchall()
    return [dict(row) for row in rows]


def clear(conn, table):
    conn.execute(f"DELETE FROM {_table(table)}")
    conn.commit()


def main(argv=None):
    parser = argparse.ArgumentParser(description="Import a CSV file into a table")
    parser.add_argument("table", choices=sorted(TABLES))
    parser.add_argument("path")
    parser.add_argument("--db", default="import.db")
    args = parser.parse_args(argv)

    conn = open_db(args.db)
    imported = import_csv(conn, args.table, args.path)
    print(f"imported {imported} rows into {args.table}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Run named maintenance jobs from a fixed registry."""

import subprocess
import time
from dataclasses import dataclass, field
from pathlib import Path

JOBS = {
    "disk-usage": ["df", "-k", "/"],
    "kernel": ["uname", "-a"],
    "user": ["id", "-un"],
    "year": ["date", "+%Y"],
}
DEFAULT_TIMEOUT = 10
LOG_SUFFIX = ".log"


@dataclass
class JobRun:
    name: str
    argv: list = field(default_factory=list)
    returncode: int = 0
    output: str = ""
    at: float = field(default_factory=time.time)

    @property
    def ok(self):
        return self.returncode == 0

    def as_line(self):
        state = "ok" if self.ok else f"exit {self.returncode}"
        return f"{self.name}: {state}"


def available_jobs():
    return sorted(JOBS)


def run_job(name, timeout=DEFAULT_TIMEOUT):
    argv = JOBS[name]
    result = subprocess.run(
        argv, capture_output=True, text=True, timeout=timeout, check=False
    )
    return JobRun(name, list(argv), result.returncode, result.stdout.strip())


def log_path(name, log_dir):
    base = Path(log_dir).resolve()
    target = (base / (name + LOG_SUFFIX)).resolve()
    if not target.is_relative_to(base):
        raise ValueError(f"{name!r} is outside the log directory")
    return target


def write_log(run, log_dir):
    target = log_path(run.name, log_dir)
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open("a", encoding="utf-8") as handle:
        handle.write(f"{int(run.at)} {run.as_line()}\n{run.output}\n")
    return target


def run_and_log(name, log_dir, timeout=DEFAULT_TIMEOUT):
    run = run_job(name, timeout)
    write_log(run, log_dir)
    return run


def run_all(log_dir=None, timeout=DEFAULT_TIMEOUT):
    runs = []
    for name in available_jobs():
        run = run_job(name, timeout)
        if log_dir is not None:
            write_log(run, log_dir)
        runs.append(run)
    return runs


def summary(runs):
    lines = [run.as_line() for run in runs]
    failed = [run.name for run in runs if not run.ok]
    lines.append(f"failed: {', '.join(failed) if failed else 'none'}")
    return "\n".join(lines)
